struct Box{Vec3 lo{},hi{};};
Box box(const V& v){auto lo=vec(v,"min_mm"),s=vec(v,"size_mm");return {lo,lo+s};}
bool inside(Vec3 p,const Box& b){return p.x>=b.lo.x&&p.x<=b.hi.x&&p.y>=b.lo.y&&p.y<=b.hi.y&&p.z>=b.lo.z&&p.z<=b.hi.z;}
bool segmentBox(Vec3 a,Vec3 b,Box box){double start=0,end=1;auto slab=[&](double p,double q,double lo,double hi){if(std::abs(q)<1e-14)return p>=lo&&p<=hi;auto l=(lo-p)/q,h=(hi-p)/q;if(l>h)std::swap(l,h);start=std::max(start,l);end=std::min(end,h);return start<=end;};auto v=b-a;return slab(a.x,v.x,box.lo.x,box.hi.x)&&slab(a.y,v.y,box.lo.y,box.hi.y)&&slab(a.z,v.z,box.lo.z,box.hi.z);}
// Exact segment-vs-cylinder-membership predicate at a voxel centre. The grid
// is an explicitly approximate removal model, never a replacement CAD B-rep.
